SELECT p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.icd_code, d.icd_version, ph.drug, ph.dose_given, ph.dose_given_unit, ph.dose_per_hour, ph.dose_unit_hour, ph.start_time, ph.end_time, ph.infusion_rate, ph.infusion_duration, ph.infusion_type, ph.is_continued, ph.is_initiated_late, ph.is_discontinued, (ph.dose_given / NULLIF(ph.dose_per_hour, 0)) * (ph.infusion_duration / NULLIF(ph.infusion_type, 0)) AS dose_factor, (ph.dose_given_unit / NULLIF(ph.dose_unit_hour, 0)) * (ph.infusion_duration / NULLIF(ph.infusion_type, 0)) AS dose_unit_factor, (ph.start_time - lag(ph.end_time) OVER (PARTITION BY p.subject_id ORDER BY ph.start_time)) / NULLIF(ph.infusion_duration, 0) AS lead_lag_factor, (ph.end_time - lag(ph.start_time) OVER (PARTITION BY p.subject_id ORDER BY ph.end_time)) / NULLIF(ph.infusion_duration, 0) AS lag_lead_factor FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN transfers t ON a.subject_id = t.subject_id JOIN labevents le ON a.subject_id = le.subject_id JOIN d_labitems dli ON le.itemid = dli.itemid JOIN prescriptions ph ON t.subject_id = ph.subject_id AND t.hadm_id = ph.hadm_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 40 AND 50 AND a.admission_type = 'IM' AND (dli.label ilike '%diabetes%' OR dli.label ilike '%heart failure%') AND (ph.drug ilike '%antidiabetic%' OR ph.drug ilike '%beta-blocker%' OR ph.drug ilike '%ACEi%' OR ph.drug ilike '%ARB%' OR ph.drug ilike '%ARNI%' OR ph.drug ilike '%loop diuretic%') AND (ph.start_time - lag(ph.end_time) OVER (PARTITION BY p.subject_id ORDER BY ph.start_time)) / NULLIF(ph.infusion_duration, 0) > 24 AND (lead(ph.end_time) OVER (PARTITION BY p.subject_id ORDER BY ph.start_time) - ph.start_time) / NULLIF(ph.infusion_duration, 0) > 24 AND (ph.is_continued = TRUE OR ph.is_initiated_late = TRUE OR ph.is_discontinued = TRUE) ORDER BY p.subject_id, ph.start_time NULLS LAST;